/*
 * Azzurra's Pro Tennis Challenge - PRG32 portable cartridge, 128 KiB profile.
 *
 * Azzurra and her partner Viola take on fourteen doubles pairs in fourteen cities,
 * from Napoli to the final in Athens, on clay, grass and hard courts, by day and
 * under floodlights.
 *
 * The rules, the ball and the computer players are in az_core.h; the sequencer in
 * az_music.h; every picture, palette and the geometry in gen/art.inc, generated by
 * tools/build_art.py. This file shows the game.
 *
 * The renderer works one screen row at a time:
 *
 *   1. A row buffer in cartridge memory is filled with the row's background: the
 *      score bar, a row of the city's skyline, or a row of the stadium and court,
 *      each a run-length row decoded on its own.
 *   2. Every sprite crossing the row is scaled into it, far to near, so that the
 *      net hides a far player's feet and a near player stands in front of the net.
 *   3. Text goes on top, and the part of the row that changed reaches the firmware
 *      as runs of one indexed colour (prg32_gfx_rect_indexed), or as one 8-bit
 *      indexed sprite when the row is too busy.
 *
 * Nothing is ever erased and no picture is ever held whole: a moved sprite's old
 * pixels vanish because its rows are rebuilt. Only rows that changed are sent,
 * which is what decides the frame rate on the ESP32-C6's SPI panel.
 *
 * Colours: every entry of the screen's compact palette owns one cell of the
 * firmware's 6x6x6 cube, and the cell is set to the exact colour
 * (prg32_palette_set), so the indexed framebuffer of the ESP32-C6 and the direct
 * colour one of QEMU show the same picture (docs/graphics.md).
 *
 * Portable cartridges have no relocations: no pointer may appear in initialised
 * static data (tools/check_relocatable.py proves it).
 */
#include "prg32.h"
#include <stddef.h>

/* The cartridge is linked with -nostdlib; the compiler may still emit calls to these
 * two for structure copies and clears. */
#ifndef AZ_HOST
void *memset(void *dst, int value, size_t n) __attribute__((optimize("no-tree-loop-distribute-patterns")));
void *memcpy(void *dst, const void *src, size_t n) __attribute__((optimize("no-tree-loop-distribute-patterns")));
void *memset(void *dst, int value, size_t n) {
    unsigned char *d = (unsigned char *)dst;
    while (n--) *d++ = (unsigned char)value;
    return dst;
}
void *memcpy(void *dst, const void *src, size_t n) {
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;
    while (n--) *d++ = *s++;
    return dst;
}
#endif

#define AZ_NOTE_ON(ch, inst, note, vol, pan) \
    prg32_audio_note_on_pan((uint8_t)(ch), (uint8_t)(inst), (uint8_t)(note), (uint8_t)(vol), (int8_t)(pan))
#define AZ_NOTE_OFF(ch) prg32_audio_note_off((uint8_t)(ch))

#include "gen/art.inc"
#include "gen/music.inc"
#include "az_core.h"
#include "az_music.h"

#define W G_GAME_W
#define H G_GAME_H
#define MAX_CATCH_UP 3u
#define MAX_SPRITES 40
#define MAX_ROW_RUNS 72
#define SPLIT_Y 118                    /* the frame is flushed in two boxes, above and below */
#define TEXT_ROWS 25
#define TEXT_COLS 40
#define ROUNDS CITY_COUNT
#define DEMO_IDLE_TICKS 450            /* 15 s on the title before the demo */
#define RESULT_GUARD_TICKS 60          /* 2 s before a result screen takes a key, so a
                                          button still held from the rally does not skip it */
#define PARTNER_NAME "VIOLA"

enum { APP_TITLE, APP_DEMO, APP_INTRO, APP_PLAY, APP_PAUSE, APP_ROUNDWON, APP_GAMEOVER, APP_CHAMPION };
enum { MENU_TOUR, MENU_EXHIBITION, MENU_GAMES, MENU_PLAYERS, MENU_COUNT };
enum { TINT_AZZURRA, TINT_PARTNER, TINT_RIVAL_A, TINT_RIVAL_B, TINT_NONE };

typedef struct {
    uint8_t id, tint, flip;
    int16_t x, y, w, h;
    uint16_t stepx, stepy;
    int16_t depth;
} spr_t;

static struct {
    /* the screen */
    uint8_t line[W + 64];
    uint8_t src[W + 64];
    uint8_t dirty[H];                  /* 0 clean, 1 whole row, 2 the span rx0..rx1 */
    int16_t rx0[H], rx1[H];
    spr_t cur[MAX_SPRITES], prev[MAX_SPRITES];
    uint8_t order[MAX_SPRITES];
    uint8_t count, prev_count;
    uint16_t palette[PALETTE_SIZE];    /* exact RGB565 of each compact index */
    uint8_t cell[PALETTE_SIZE];        /* and the cube cell that shows it */
    uint8_t tint[4][32];               /* sprite colour -> compact index, per player */
    prg32_indexed_sprite_t row;
    uint8_t city, court, scene_city;
    /* the text layer: 40 x 25 cells of 8 x 8 */
    char text[TEXT_ROWS][TEXT_COLS];
    uint8_t tcol[TEXT_ROWS][TEXT_COLS];
    uint8_t panel0[TEXT_ROWS], panel1[TEXT_ROWS];   /* panel columns [panel0, panel1) */
    uint8_t big[TEXT_ROWS];
    uint8_t hud;
    /* the app */
    uint8_t app, menu, exhibition_city, games_to_win, players, exhibition;
    uint8_t round;
    uint16_t app_tick, idle;
    uint8_t banner_ticks;
    uint8_t demo_city;
    uint32_t last_ms, tick_accum, last_input, pending_pressed, pending_pressed2, last_input2;
    uint32_t seed;
    az_music_t music;
    az_game_t game;
    uint8_t conf_x[24], conf_y[24], conf_k[24];
} v;

/* ---- colours ------------------------------------------------------------------- */

static void city_load(int city) {
    v.city = (uint8_t)city;
    v.court = city_surface[city];
    const uint16_t *pal = city_palette + city * PALETTE_SIZE;
    for (int i = 0; i < PALETTE_SIZE; ++i) {
        uint16_t c = pal[i];
        v.palette[i] = c;
        /* The firmware's quantiser (tools/palette.py: cube_index). */
        static const uint16_t named[8] = {0x0000, 0xffff, 0xf800, 0x07e0, 0x001f, 0xffe0, 0x07ff, 0xf81f};
        uint8_t cell = 0;
        int k;
        for (k = 0; k < 8 && named[k] != c; ++k) {}
        if (k < 8) {
            cell = (uint8_t)k;
        } else {
            unsigned r = ((c >> 11) & 31u) * 5u / 31u, g = ((c >> 5) & 63u) * 5u / 63u, b = (c & 31u) * 5u / 31u;
            cell = (uint8_t)(16u + r * 36u + g * 6u + b);
        }
        v.cell[i] = cell;
    }
    for (int i = 0; i < PALETTE_SIZE; ++i) prg32_palette_set(v.cell[i], v.palette[i]);
    /* Player colours: Azzurra in azure with blonde hair, Viola in azure with brown,
     * the rivals in their city's colours. */
    static const uint8_t hairs[4] = {C_BLONDE, C_BROWN, C_DARK, C_GREYD};
    static const uint8_t skins[3][2] = {{C_SKIN, C_SKIND}, {C_SKIND, C_BROWN}, {C_SKINL, C_SKIN}};
    for (int t = 0; t < 4; ++t) {
        for (int i = 0; i < 32; ++i) v.tint[t][i] = (uint8_t)i;
        int hair = t == 0 ? C_BLONDE : t == 1 ? C_BROWN : hairs[(city * 3 + t) & 3];
        int skin = t < 2 ? (t == 0 ? 0 : 2) : (city + t) % 3;
        v.tint[t][C_BLONDE] = (uint8_t)hair;
        v.tint[t][C_SKIN] = skins[skin][0];
        v.tint[t][C_SKIND] = skins[skin][1];
        if (t >= 2) {
            v.tint[t][C_SHIRT] = S_RIVAL;
            v.tint[t][C_SHIRTD] = S_RIVALD;
        }
    }
}

/* ---- dirty rows ---------------------------------------------------------------------- */

static void mark_span(int y, int x0, int x1) {
    if (y < 0 || y >= H || v.dirty[y] == 1) return;
    if (x0 < 0) x0 = 0;
    if (x1 > W) x1 = W;
    if (x0 >= x1) return;
    if (v.dirty[y] == 0) {
        v.dirty[y] = 2;
        v.rx0[y] = (int16_t)x0;
        v.rx1[y] = (int16_t)x1;
    } else {
        if (x0 < v.rx0[y]) v.rx0[y] = (int16_t)x0;
        if (x1 > v.rx1[y]) v.rx1[y] = (int16_t)x1;
    }
}

static void dirty_all(void) {
    for (int y = 0; y < H; ++y) v.dirty[y] = 1;
}

/* ---- text ------------------------------------------------------------------------------ */

static int text_y0(int cy) { return cy == 0 ? 1 : cy * 8; }

static void text_dirty(int cy) {
    int y0 = text_y0(cy), y1 = y0 + (v.big[cy] ? 16 : 8);
    for (int y = y0; y < y1; ++y) mark_span(y, 0, W);
}

static void text_clear_line(int cy) {
    int changed = v.panel1[cy] != 0 || v.big[cy];
    for (int x = 0; x < TEXT_COLS; ++x) {
        if (v.text[cy][x] != ' ') changed = 1;
        v.text[cy][x] = ' ';
    }
    if (changed) text_dirty(cy);
    v.panel0[cy] = v.panel1[cy] = 0;
    v.big[cy] = 0;
}

static void text_clear(void) {
    for (int cy = 0; cy < TEXT_ROWS; ++cy) text_clear_line(cy);
}

static int text_len(const char *s) {
    int n = 0;
    while (s[n]) ++n;
    return n;
}

static void text_at(int col, int cy, const char *s, int color) {
    for (int i = 0; s[i] && col + i < TEXT_COLS; ++i) {
        if (col + i < 0) continue;
        if (v.text[cy][col + i] != s[i] || v.tcol[cy][col + i] != color) {
            v.text[cy][col + i] = s[i];
            v.tcol[cy][col + i] = (uint8_t)color;
            text_dirty(cy);
        }
    }
}

static void text_center(int cy, const char *s, int color) {
    int cols = v.big[cy] ? 20 : TEXT_COLS;
    text_at((cols - text_len(s)) / 2, cy, s, color);
}

static void text_panel(int cy0, int cy1, int col0, int col1) {
    for (int cy = cy0; cy <= cy1; ++cy) {
        if (v.panel0[cy] != col0 || v.panel1[cy] != col1) text_dirty(cy);
        v.panel0[cy] = (uint8_t)col0;
        v.panel1[cy] = (uint8_t)col1;
    }
}

static void text_big(int cy, const char *s, int color) {
    text_clear_line(cy);
    text_clear_line(cy + 1);
    v.big[cy] = 1;
    text_center(cy, s, color);
    text_dirty(cy);
}

static const uint8_t *glyph_of(char c) {
    int k = (int)(unsigned char)c - 32;
    if (k >= 64) k -= 32;                         /* lower case as capitals */
    return font_bits + ((k < 0 || k >= 64) ? 0 : k) * 8;
}

static void draw_text_row(uint8_t *line, int y) {
    int cy, row;
    if (v.hud && y < G_HUD_H) {
        cy = 0;
        row = y - 1;
        if (row < 0 || row > 7) return;
    } else {
        cy = y >> 3;
        row = y & 7;
        if (v.hud && cy == 1) return;
    }
    if (v.panel1[cy]) {
        int x0 = v.panel0[cy] * 8, x1 = v.panel1[cy] * 8;
        for (int x = x0; x < x1; ++x) line[x] = C_PANEL;
        if (row == 0 && (cy == 0 || !v.panel1[cy - 1])) for (int x = x0; x < x1; ++x) line[x] = C_PANELL;
        if (row == 7 && (cy == TEXT_ROWS - 1 || !v.panel1[cy + 1])) for (int x = x0; x < x1; ++x) line[x] = C_PANELL;
    }
    if (cy > 0 && v.big[cy - 1]) {
        cy -= 1;
        row += 8;
    }
    if (v.big[cy]) {
        int gy = row >> 1, shadow = (row - 2) >> 1;
        for (int c = 0; c < 20; ++c) {
            char ch = v.text[cy][c];
            if (ch == ' ') continue;
            const uint8_t *gl = glyph_of(ch);
            unsigned bits = gl[gy], under = row >= 2 ? gl[shadow] : 0;
            int left = c * 16, color = v.tcol[cy][c];
            for (int k = 0; k < 8; ++k) {
                int px = left + k * 2;
                if ((under >> (7 - k)) & 1u) line[px + 2] = line[px + 3] = C_INK;
                if ((bits >> (7 - k)) & 1u) line[px] = line[px + 1] = (uint8_t)color;
            }
        }
        return;
    }
    int panel = v.panel1[cy] != 0 || (v.hud && cy == 0);
    for (int c = 0; c < TEXT_COLS; ++c) {
        char ch = v.text[cy][c];
        if (ch == ' ') continue;
        const uint8_t *gl = glyph_of(ch);
        unsigned bits = gl[row], under = row > 0 ? gl[row - 1] : 0;
        int left = c * 8, color = v.tcol[cy][c];
        for (int k = 0; k < 8; ++k) {
            /* Over the picture, letters get a shadow so they read on any background. */
            if (!panel && ((under >> (7 - k)) & 1u)) line[left + k + 1] = C_INK;
            if ((bits >> (7 - k)) & 1u) line[left + k] = (uint8_t)color;
        }
    }
}

/* ---- sprites ---------------------------------------------------------------------------- */

static void sprite_add(int id, int x, int y, int w, int h, int tint, int flip, int depth) {
    if (v.count == MAX_SPRITES || w < 1 || h < 1) return;
    if (x + w <= 0 || x >= W || y >= H || y + h <= 0) return;
    spr_t *s = &v.cur[v.count++];
    s->id = (uint8_t)id;
    s->x = (int16_t)x;
    s->y = (int16_t)y;
    s->w = (int16_t)w;
    s->h = (int16_t)h;
    s->stepx = (uint16_t)(((unsigned)spr_w[id] << 8) / (unsigned)w);
    s->stepy = (uint16_t)(((unsigned)spr_h[id] << 8) / (unsigned)h);
    s->tint = (uint8_t)tint;
    s->flip = (uint8_t)flip;
    s->depth = (int16_t)depth;
}

static void sprite_add_1x(int id, int x, int y, int depth) {
    sprite_add(id, x, y, spr_w[id], spr_h[id], TINT_NONE, 0, depth);
}

/* A run-length row: (index << shift) | run, or run 0 and the run in the next byte. */
static void decode_row(const uint8_t *data, uint8_t *out, int width, int shift) {
    int x = 0;
    unsigned mask = (1u << shift) - 1u;
    while (x < width) {
        unsigned b = *data++;
        unsigned run = b & mask;
        uint8_t value = (uint8_t)(b >> shift);
        if (!run) run = *data++;
        while (run-- && x < width) out[x++] = value;
    }
}

static void blit_sprite_row(const spr_t *s, uint8_t *line, int y) {
    int id = s->id;
    int sy = ((y - s->y) * s->stepy) >> 8;
    if (sy >= spr_h[id]) sy = spr_h[id] - 1;
    decode_row(spr_data + spr_rows[spr_first[id] + sy], v.src, spr_w[id], 3);
    int x = s->x;
    int dx0 = 0, dx1 = s->w;
    if (x < 0) dx0 = -x;
    if (x + dx1 > W) dx1 = W - x;
    const uint8_t *tint = s->tint < TINT_NONE ? v.tint[s->tint] : 0;
    uint8_t *dst = line + x + dx0;
    int last = spr_w[id] - 1;
    for (int dx = dx0; dx < dx1; ++dx) {
        unsigned sx = ((unsigned)dx * s->stepx) >> 8;
        if ((int)sx > last) sx = (unsigned)last;
        uint8_t c = v.src[s->flip ? last - (int)sx : (int)sx];
        if (c != SPR_TRANSPARENT) *dst = tint ? tint[c] : c;
        ++dst;
    }
}

static void send_row(const uint8_t *line, int y, int x0, int x1) {
    int runs = 1;
    for (int x = x0 + 1; x < x1 && runs <= MAX_ROW_RUNS; ++x) runs += line[x] != line[x - 1];
    if (runs > MAX_ROW_RUNS) {
        v.row.pixels = line + x0;
        v.row.width = (uint16_t)(x1 - x0);
        prg32_sprite_draw_indexed(x0, y, &v.row, 0);
        return;
    }
    int x = x0;
    while (x < x1) {
        uint8_t color = line[x];
        int end = x + 1;
        while (end < x1 && line[end] == color) ++end;
        prg32_gfx_rect_indexed(x, y, end - x, 1, v.cell[color]);
        x = end;
    }
}

static void draw_row(int y, int x0, int x1) {
    uint8_t *line = v.line;
    if (v.hud && y < G_HUD_H) {
        for (int x = 0; x < W; ++x) line[x] = y == G_HUD_H - 1 ? C_HUDLINE : C_HUDBAR;
    } else if (y < G_COURT_Y) {
        int r = y - G_VIEW_Y;
        if (r < 0) r = 0;
        decode_row(view_data + view_rows[v.city * G_VIEW_H + r], line, W, 2);
        const uint8_t *map = view_map + v.city * 64;
        for (int x = 0; x < W; ++x) line[x] = map[line[x]];
    } else {
        decode_row(court_data + court_rows[v.court * COURT_ROWS + (y - G_COURT_Y)], line, W, 2);
    }
    for (int k = 0; k < v.count; ++k) {
        const spr_t *s = &v.cur[v.order[k]];
        if (y >= s->y && y < s->y + s->h) blit_sprite_row(s, line, y);
    }
    draw_text_row(line, y);
    send_row(line, y, x0, x1);
}

static void mark_sprite(const spr_t *s) {
    int y0 = s->y < 0 ? 0 : s->y, y1 = s->y + s->h;
    if (y1 > H) y1 = H;
    for (int y = y0; y < y1; ++y) mark_span(y, s->x, s->x + s->w);
}

static void render(void) {
    /* Depth order, far to near: insertion sort of a handful. */
    for (int i = 0; i < v.count; ++i) {
        int k = i;
        while (k > 0 && v.cur[v.order[k - 1]].depth > v.cur[i].depth) {
            v.order[k] = v.order[k - 1];
            --k;
        }
        v.order[k] = (uint8_t)i;
    }
    int n = v.count > v.prev_count ? v.count : v.prev_count;
    for (int i = 0; i < n; ++i) {
        if (i < v.count && i < v.prev_count) {
            const spr_t *a = &v.cur[i], *b = &v.prev[i];
            if (a->id == b->id && a->x == b->x && a->y == b->y && a->w == b->w && a->h == b->h &&
                a->tint == b->tint && a->flip == b->flip && a->depth == b->depth) continue;
        }
        if (i < v.count) mark_sprite(&v.cur[i]);
        if (i < v.prev_count) mark_sprite(&v.prev[i]);
    }
    int sent = 0;
    for (int y = 0; y < H; ++y) {
        if (v.dirty[y]) {
            int whole = v.dirty[y] == 1;
            draw_row(y, whole ? 0 : v.rx0[y], whole ? W : v.rx1[y]);
            v.dirty[y] = 0;
            sent = 1;
        }
        /* Two boxes a frame, no more: on the board a present has a fixed cost, and the
         * far and near halves of the court rarely change together over all rows. */
        if (sent && y == SPLIT_Y - 1) {
            prg32_gfx_present();
            sent = 0;
        }
    }
    for (int i = 0; i < v.count; ++i) v.prev[i] = v.cur[i];
    v.prev_count = v.count;
}

/* ---- the scene ---------------------------------------------------------------------------- */

static void scene(int city) {
    if (city != v.scene_city) {
        v.scene_city = (uint8_t)city;
        city_load(city);
        dirty_all();
    }
}

static void add_static(void) {
    sprite_add_1x(SPR_NET, NET_X, NET_Y, 0);
    for (int k = 0; k < BOARD_SLOTS; ++k) sprite_add_1x(SPR_BOARD0 + (v.city + k) % SPONSOR_COUNT, board_x[k], BOARD_Y, -32000);
}

static int player_frame(const az_player_t *p, int t) {
    if (p->cheer) return (t >> 3) & 1 ? PF_CHEER : PF_READY;
    if (p->swing) {
        if (p->shot == SHOT_SERVE || p->shot == SHOT_SMASH) return p->swing < 4 ? PF_SMASH : PF_FOLLOW;
        if (p->swing < AZ_SWING_OPEN + 2) return PF_BACK;
        if (p->swing < AZ_SWING_OPEN + 6) return PF_HIT;
        return PF_FOLLOW;
    }
    return -1;
}

static void add_player(int i) {
    const az_game_t *g = &v.game;
    const az_player_t *p = &g->p[i];
    int near = p->team == AZ_NEAR;
    int frame = player_frame(p, v.app_tick);
    if (frame < 0) {
        if (g->state == PS_SERVE && i == g->server && (g->ball.tossed || g->ball.held)) frame = g->ball.tossed ? PF_TOSS : PF_READY;
        else if (p->moving) frame = (p->step >> 2) & 1 ? PF_RUN1 : PF_RUN2;
        else frame = PF_READY;
    }
    int id = (near ? SPR_BACK_READY : SPR_FRONT_READY) + frame;
    int h = az_px(232, p->y);
    int w = spr_w[id] * h / spr_h[id];
    int sx = az_sx(p->x, p->y), sy = az_sy(p->y, 0);
    int flip = p->swing ? p->backhand : 0;
    int sw = az_px(78, p->y), sh = sw / 4 + 1;
    sprite_add(SPR_SHADOW, sx - sw / 2, sy - sh / 2, sw, sh, TINT_NONE, 0, -31000);
    sprite_add(id, sx - w / 2, sy - h + 1, w, h, i, flip, p->y);
}

static void add_ball(void) {
    const az_ball_t *b = &v.game.ball;
    int x = b->x / AZ_Q, y = b->y / AZ_Q, z = b->z / AZ_Q;
    if (z < 0) z = 0;
    int size = az_px(19, y);
    if (size < 3) size = 3;
    int sx = az_sx(x, y), sy = az_sy(y, z);
    /* In the hand the ball is drawn in front of the server. */
    int depth = y + (b->held ? 40 : 1);
    if (!b->held) {
        int gy = az_sy(y, 0), sw = size + 1;
        sprite_add(SPR_BSHADOW, sx - sw / 2, gy - 1, sw, 2, TINT_NONE, 0, -30000);
    }
    sprite_add(SPR_BALL, sx - size / 2, sy - size / 2, size, size, TINT_NONE, 0, depth);
}

static void add_match(void) {
    add_static();
    for (int i = 0; i < 4; ++i) add_player(i);
    add_ball();
}

/* ---- the score bar --------------------------------------------------------------------- */

static void points_text(char *out, int team) {
    const az_game_t *g = &v.game;
    int a = g->points[team], b = g->points[1 - team];
    if (g->tiebreak) {
        int k = 0;
        if (a >= 10) out[k++] = (char)('0' + a / 10);
        out[k++] = (char)('0' + a % 10);
        out[k] = 0;
        return;
    }
    static const char names[5][3] = {"0", "15", "30", "40", "AD"};
    int n = a;
    if (a >= 3 && b >= 3) n = a > b ? 4 : 3;
    if (a >= 3 && b >= 3 && a < b) n = 3;
    out[0] = names[n][0];
    out[1] = names[n][1];
    out[2] = 0;
}

static void hud_update(void) {
    const az_game_t *g = &v.game;
    char line[TEXT_COLS + 1];
    for (int i = 0; i < TEXT_COLS; ++i) line[i] = ' ';
    line[TEXT_COLS] = 0;
    char p0[3], p1[3];
    points_text(p0, 0);
    points_text(p1, 1);
    int serving = g->p[g->server].team;
    /* AZZURRA 2  40 ...  city  ... 15  1 RIVALS */
    const char *a = "AZZURRA";
    for (int i = 0; a[i]; ++i) line[1 + i] = a[i];
    line[0] = serving == 0 ? '*' : ' ';
    line[9] = (char)('0' + g->games[0] % 10);
    line[11] = p0[0];
    line[12] = p0[1] ? p0[1] : ' ';
    const char *r = "RIVALS";
    for (int i = 0; r[i]; ++i) line[33 + i] = r[i];
    line[39] = serving == 1 ? '*' : ' ';
    line[31] = (char)('0' + g->games[1] % 10);
    int len1 = p1[1] ? 2 : 1;
    line[29 - len1 + 1] = p1[0];
    if (len1 == 2) line[29] = p1[1];
    const char *c = city_names[v.city];      /* in an exhibition and the demo too */
    if (g->tiebreak) c = "TIE-BREAK";
    int cl = text_len(c);
    if (cl > 14) cl = 14;
    int c0 = 14 + (14 - cl) / 2;
    for (int i = 0; i < cl; ++i) line[c0 + i] = c[i];
    for (int i = 0; i < TEXT_COLS; ++i) {
        int color = C_CREAM;
        if (i == 0 || i == 39) color = C_BALL;
        else if (i >= 1 && i <= 7) color = C_CYAN;
        else if (i >= 33 && i <= 38) color = C_RED;
        else if (i >= 9 && i <= 12) color = C_WHITE;
        else if (i >= 28 && i <= 31) color = C_WHITE;
        else color = C_GOLD;
        char s[2] = {line[i], 0};
        text_at(i, 0, s, color);
    }
}

/* ---- audio ---------------------------------------------------------------------------- */

static int pan_of(int x) {
    int pan = x * 60 / 640;
    return pan < -60 ? -60 : pan > 60 ? 60 : pan;
}

static void sfx(int which, int x) { az_sfx_play(&v.music, which, pan_of(x), 0); }

/* ---- screens ----------------------------------------------------------------------------- */

static void set_app(int app) {
    v.app = (uint8_t)app;
    v.app_tick = 0;
}

static void say(int cy, const char *s, int color, int ticks) {
    text_clear_line(cy);
    text_panel(cy, cy, 8, 32);
    text_center(cy, s, color);
    v.banner_ticks = (uint8_t)ticks;
}

static void number(char *out, int n) {
    if (n >= 10) {
        *out++ = (char)('0' + n / 10);
    }
    *out++ = (char)('0' + n % 10);
    *out = 0;
}

static void score_line(char *out, int a, int b) {
    number(out, a);
    int k = text_len(out);
    out[k++] = '-';
    number(out + k, b);
}

static const char *menu_label(int item, char *buf) {
    const char *s;
    int k = 0;
    switch (item) {
    case MENU_TOUR: return "START WORLD TOUR";
    case MENU_EXHIBITION:
        s = "EXHIBITION: ";
        while (*s) buf[k++] = *s++;
        s = city_names[v.exhibition_city];
        break;
    case MENU_GAMES:
        s = "GAMES PER SET: ";
        while (*s) buf[k++] = *s++;
        buf[k++] = (char)('0' + v.games_to_win);
        s = v.games_to_win == 4 ? " (TIE-BREAK)" : "";
        break;
    default:
        s = "PLAYERS: ";
        while (*s) buf[k++] = *s++;
        s = v.players == 2 ? "2 (P2 = VIOLA)" : "1";
        break;
    }
    while (*s) buf[k++] = *s++;
    buf[k] = 0;
    return buf;
}

static void title_menu(void) {
    char buf[TEXT_COLS + 1];
    for (int i = 0; i < MENU_COUNT; ++i) {
        int cy = 19 + i;
        text_clear_line(cy);
        text_panel(cy, cy, 3, 37);
        const char *label = menu_label(i, buf);
        text_center(cy, label, i == v.menu ? C_GOLD : C_CREAM);
        if (i == v.menu) {
            int col = (TEXT_COLS - text_len(label)) / 2 - 2;
            text_at(col, cy, ">", C_BALL);
        }
    }
}

static void setup_players_idle(int city) {
    /* A posed match for the title: everyone at the baseline. */
    az_game_t *g = &v.game;
    for (int i = 0; i < 4; ++i) g->p[i].human = 0;
    az_new_match(g, 0, city_surface[city], 1, 1u, 0);
}

static void title_screen(void) {
    set_app(APP_TITLE);
    v.hud = 0;
    v.exhibition = 0;
    v.idle = 0;
    text_clear();
    scene(0);
    dirty_all();
    setup_players_idle(0);
    title_menu();
    text_center(24, "UNIPARTHENOPE  RISC-V  PRG32  2026", C_GREY);
    az_music_play(&v.music, SONG_TITLE);
}

static void start_match(int city, int demo) {
    az_game_t *g = &v.game;
    for (int i = 0; i < 4; ++i) g->p[i].human = 0;
    if (!demo) {
        g->p[0].human = 1;
        if (v.players == 2) g->p[1].human = 1;
    }
    int level = v.exhibition ? city : v.round;
    v.seed = v.seed * 1103515245u + 12345u + v.app_tick;
    az_new_match(g, level, city_surface[city], demo ? 1 : v.games_to_win, v.seed, (city & 1) ? 1 : 0);
}

static void intro_screen(void) {
    set_app(APP_INTRO);
    az_music_stop(&v.music);
    int city = v.exhibition ? v.exhibition_city : v.round;
    scene(city);
    start_match(city, 0);
    v.hud = 1;
    text_clear();
    dirty_all();
    hud_update();
    char buf[24];
    text_panel(6, 14, 4, 36);
    if (v.exhibition) {
        text_center(7, "EXHIBITION MATCH", C_CYAN);
    } else {
        const char *s = "ROUND ";
        int k = 0;
        while (*s) buf[k++] = *s++;
        number(buf + k, v.round + 1);
        k = text_len(buf);
        s = " OF 14";
        while (*s) buf[k++] = *s++;
        buf[k] = 0;
        text_center(7, buf, C_CYAN);
    }
    text_big(8, city_names[city], C_GOLD);
    text_panel(8, 9, 4, 36);
    text_center(11, "VS", C_GREY);
    text_center(12, rival_names[city], C_RED);
    text_center(14, surface_names[city_surface[city]], C_CREAM);
    sfx(SFX_APPLAUSE, 0);
}

static void play_screen(void) {
    set_app(APP_PLAY);
    for (int cy = 2; cy < TEXT_ROWS; ++cy) text_clear_line(cy);
    hud_update();
}

static void result_text(int cy, int team) {
    char buf[32];
    const az_game_t *g = &v.game;
    score_line(buf, g->games[team], g->games[1 - team]);
    text_center(cy, buf, C_CREAM);
}

static void roundwon_screen(void) {
    set_app(APP_ROUNDWON);
    az_music_play(&v.music, SONG_ROUNDWON);
    for (int cy = 2; cy < TEXT_ROWS; ++cy) text_clear_line(cy);
    text_panel(5, 13, 4, 36);
    text_big(6, v.exhibition ? "WELL PLAYED!" : "ROUND WON!", C_GOLD);
    text_panel(6, 7, 4, 36);
    text_center(9, "AZZURRA & " PARTNER_NAME, C_CYAN);
    result_text(10, 0);
    if (!v.exhibition) {
        char buf[32];
        const char *s = "NEXT: ";
        int k = 0;
        while (*s) buf[k++] = *s++;
        for (s = city_names[v.round + 1]; *s; ++s) buf[k++] = *s;
        buf[k] = 0;
        text_center(12, buf, C_CREAM);
    }
    text_center(13, "PRESS A", C_BALL);
}

static void gameover_screen(void) {
    set_app(APP_GAMEOVER);
    az_music_play(&v.music, SONG_GAMEOVER);
    for (int cy = 2; cy < TEXT_ROWS; ++cy) text_clear_line(cy);
    text_panel(5, 13, 4, 36);
    text_big(6, "GAME OVER", C_RED);
    text_panel(6, 7, 4, 36);
    int city = v.exhibition ? v.exhibition_city : v.round;
    text_center(9, rival_names[city], C_RED);
    text_center(10, "TAKE THE MATCH", C_CREAM);
    result_text(11, 1);
    text_center(13, v.exhibition ? "A: TITLE" : "A: TRY AGAIN   B: TITLE", C_BALL);
}

static void champion_screen(void) {
    set_app(APP_CHAMPION);
    az_music_play(&v.music, SONG_CHAMPION);
    v.hud = 0;
    text_clear();
    dirty_all();
    text_big(1, "GRAND SLAM", C_GOLD);
    text_big(3, "CHAMPIONS!", C_GOLD);
    text_panel(20, 22, 4, 36);
    text_center(20, "AZZURRA & " PARTNER_NAME, C_CYAN);
    text_center(21, "14 CITIES - 14 TITLES", C_CREAM);
    text_center(22, "PRESS A", C_BALL);
    for (int i = 0; i < 24; ++i) {
        v.conf_x[i] = (uint8_t)((i * 53 + 17) % 250);
        v.conf_y[i] = (uint8_t)((i * 37) % 200);
        v.conf_k[i] = (uint8_t)(i % 6);
    }
    az_game_t *g = &v.game;
    for (int i = 0; i < 4; ++i) g->p[i].cheer = g->p[i].team == AZ_NEAR;
}

static void demo_screen(void) {
    set_app(APP_DEMO);
    az_music_stop(&v.music);
    v.demo_city = (uint8_t)((v.demo_city + 5) % CITY_COUNT);
    scene(v.demo_city);
    v.exhibition = 1;
    start_match(v.demo_city, 1);
    v.hud = 1;
    text_clear();
    dirty_all();
    hud_update();
}

/* ---- game events ---------------------------------------------------------------------------- */

static void handle_events(void) {
    az_game_t *g = &v.game;
    char call[24];
    for (int i = 0; i < g->event_count; ++i) {
        const az_event_t *e = &g->events[i];
        switch (e->type) {
        case EV_TOSS: sfx(SFX_TOSS, e->x); break;
        case EV_HIT:
            sfx(e->value == SHOT_LOB ? SFX_LOB : e->value == SHOT_SERVE || e->value == SHOT_SMASH ? SFX_SERVE
                : e->value == SHOT_VOLLEY ? SFX_VOLLEY : SFX_FLAT, e->x);
            break;
        case EV_BOUNCE: if (e->value < 3) sfx(SFX_BOUNCE, e->x); break;
        case EV_NET: sfx(SFX_NET, e->x); break;
        case EV_OUT: sfx(SFX_OUT, e->x); say(7, "OUT!", C_RED, 50); break;
        case EV_FAULT: sfx(SFX_FAULT, e->x); say(7, "FAULT", C_RED, 50); break;
        case EV_DOUBLE_FAULT: say(7, "DOUBLE FAULT", C_RED, 55); break;
        case EV_LET: sfx(SFX_LET, e->x); say(7, "LET", C_GOLD, 50); break;
        case EV_POINT:
            if (v.app == APP_PLAY) sfx(e->value == 0 ? SFX_WON : SFX_LOST, 0);
            if (e->value == 0 || v.app == APP_DEMO) sfx(SFX_APPLAUSE, 0);
            break;
        case EV_GAME: sfx(SFX_GAME, 0); break;
        default: break;
        }
    }
    /* After a point: the umpire's call. */
    for (int i = 0; i < g->event_count; ++i) {
        const az_event_t *e = &g->events[i];
        if (e->type == EV_MATCH) {
            say(7, e->value == 0 ? "GAME, SET AND MATCH!" : "MATCH TO THE RIVALS", e->value == 0 ? C_GOLD : C_RED, 90);
        } else if (e->type == EV_GAME) {
            say(7, e->value == 0 ? "GAME AZZURRA" : "GAME RIVALS", C_GOLD, 60);
        } else if (e->type == EV_TIEBREAK) {
            say(7, "TIE-BREAK!", C_GOLD, 60);
        } else if (e->type == EV_POINT && i == g->event_count - 1) {
            int had_banner = v.banner_ticks > 0;
            az_call(g, call);
            if (!had_banner) say(7, call, C_CREAM, 45);
            else {
                text_clear_line(8);
                text_panel(8, 8, 8, 32);
                text_center(8, call, C_CREAM);
            }
        }
    }
}

/* ---- input ----------------------------------------------------------------------------- */

static uint32_t to_core(uint32_t b) {
    uint32_t in = 0;
    if (b & PRG32_BTN_LEFT) in |= AZ_LEFT;
    if (b & PRG32_BTN_RIGHT) in |= AZ_RIGHT;
    if (b & PRG32_BTN_UP) in |= AZ_UP;
    if (b & PRG32_BTN_DOWN) in |= AZ_DOWN;
    if (b & PRG32_BTN_A) in |= AZ_A;
    if (b & PRG32_BTN_B) in |= AZ_B;
    return in;
}

#define ANY_BUTTON (PRG32_BTN_A | PRG32_BTN_B | PRG32_BTN_START)

static void menu_input(uint32_t pressed) {
    int changed = 0;
    if (pressed & PRG32_BTN_UP) {
        v.menu = (uint8_t)((v.menu + MENU_COUNT - 1) % MENU_COUNT);
        changed = 1;
    }
    if (pressed & PRG32_BTN_DOWN) {
        v.menu = (uint8_t)((v.menu + 1) % MENU_COUNT);
        changed = 1;
    }
    int dir = (pressed & PRG32_BTN_RIGHT) ? 1 : (pressed & PRG32_BTN_LEFT) ? -1 : 0;
    if (dir) {
        if (v.menu == MENU_EXHIBITION) v.exhibition_city = (uint8_t)((v.exhibition_city + CITY_COUNT + dir) % CITY_COUNT);
        else if (v.menu == MENU_GAMES) v.games_to_win = (uint8_t)(v.games_to_win == 1 ? (dir > 0 ? 2 : 4) : v.games_to_win == 2 ? (dir > 0 ? 4 : 1) : (dir > 0 ? 1 : 2));
        else if (v.menu == MENU_PLAYERS) v.players = (uint8_t)(v.players == 1 ? 2 : 1);
        changed = 1;
    }
    if (changed) {
        az_sfx_play(&v.music, SFX_MENU, 0, 0);
        title_menu();
        v.idle = 0;
    }
    if (pressed & (PRG32_BTN_A | PRG32_BTN_START)) {
        az_sfx_play(&v.music, SFX_SELECT, 0, 0);
        if (v.menu == MENU_TOUR) {
            v.exhibition = 0;
            v.round = 0;
            intro_screen();
        } else if (v.menu == MENU_EXHIBITION) {
            v.exhibition = 1;
            intro_screen();
        } else {
            menu_input(PRG32_BTN_RIGHT);
        }
    }
}

static void update_step(uint32_t held, uint32_t pressed, uint32_t held2, uint32_t pressed2) {
    az_game_t *g = &v.game;
    v.app_tick++;
    az_music_tick(&v.music);
    if (v.banner_ticks && --v.banner_ticks == 0 && (v.app == APP_PLAY || v.app == APP_DEMO)) {
        text_clear_line(7);
        text_clear_line(8);
    }
    switch (v.app) {
    case APP_TITLE:
        if (pressed) v.idle = 0;
        else if (++v.idle > DEMO_IDLE_TICKS) {
            demo_screen();
            break;
        }
        menu_input(pressed);
        break;
    case APP_DEMO: {
        uint32_t none[4] = {0, 0, 0, 0};
        if (pressed & (ANY_BUTTON | PRG32_BTN_SELECT)) {
            title_screen();
            break;
        }
        az_tick(g, none, none);
        handle_events();
        if (g->state == PS_DEAD && g->timer > 50) {
            if (g->match_over) demo_screen();
            else az_next_point(g);
        }
        hud_update();
        if ((v.app_tick & 31u) == 0) text_center(23, "DEMO", C_GOLD);
        if ((v.app_tick & 31u) == 16) text_center(23, "    ", C_GOLD);
        break;
    }
    case APP_INTRO:
        if (v.app_tick > 100 || (pressed & ANY_BUTTON)) play_screen();
        break;
    case APP_PLAY: {
        if (pressed & PRG32_BTN_START) {
            set_app(APP_PAUSE);
            text_panel(11, 13, 6, 34);
            text_center(11, "PAUSED", C_GOLD);
            text_center(12, "START: RESUME", C_CREAM);
            text_center(13, "SELECT: QUIT TO TITLE", C_CREAM);
            break;
        }
        uint32_t h[4] = {to_core(held), to_core(held2), 0, 0};
        uint32_t p[4] = {to_core(pressed), to_core(pressed2), 0, 0};
        az_tick(g, h, p);
        handle_events();
        if (g->state == PS_DEAD) {
            if (g->match_over) {
                if (g->timer > 90) {
                    if (g->match_winner == 0) {
                        if (!v.exhibition && v.round + 1 >= ROUNDS) champion_screen();
                        else roundwon_screen();
                    } else {
                        gameover_screen();
                    }
                }
            } else if (g->timer > 50) {
                az_next_point(g);
            }
        }
        hud_update();
        break;
    }
    case APP_PAUSE:
        if (pressed & PRG32_BTN_START) {
            set_app(APP_PLAY);
            for (int cy = 11; cy <= 13; ++cy) text_clear_line(cy);
        } else if (pressed & PRG32_BTN_SELECT) {
            title_screen();
        }
        break;
    case APP_ROUNDWON: {
        uint32_t none[4] = {0, 0, 0, 0};
        az_tick(g, none, none);
        if (v.app_tick > RESULT_GUARD_TICKS && (pressed & ANY_BUTTON)) {
            az_music_stop(&v.music);
            if (v.exhibition) title_screen();
            else {
                v.round++;
                intro_screen();
            }
        }
        break;
    }
    case APP_GAMEOVER: {
        uint32_t none[4] = {0, 0, 0, 0};
        az_tick(g, none, none);
        if (v.app_tick > RESULT_GUARD_TICKS) {
            if (!v.exhibition && (pressed & PRG32_BTN_A)) {
                az_music_stop(&v.music);
                intro_screen();
            } else if (pressed & (PRG32_BTN_B | PRG32_BTN_START | (v.exhibition ? PRG32_BTN_A : 0))) {
                title_screen();
            }
        }
        break;
    }
    case APP_CHAMPION:
        for (int i = 0; i < 24; ++i) {
            v.conf_y[i] = (uint8_t)(v.conf_y[i] + 1 + (i & 1));
            if (v.conf_y[i] > 196) v.conf_y[i] = 0;
        }
        if (v.app_tick > RESULT_GUARD_TICKS + 15 && (pressed & ANY_BUTTON)) title_screen();
        break;
    default:
        break;
    }
}

/* ---- the three cartridge entry points ------------------------------------------------------ */

void azzurra_init(void) {
    uint8_t *raw = (uint8_t *)&v;
    for (unsigned i = 0; i < sizeof(v); ++i) raw[i] = 0;
    v.row.palette = v.palette;
    v.row.palette_count = PALETTE_SIZE;
    v.row.width = W;
    v.row.height = 1;
    v.row.frame_count = 1;
    v.row.bits_per_pixel = PRG32_SPRITE_BPP_8;
    v.row.transparent_index = -1;
    v.row.pixels = v.line;
    for (int y = 0; y < TEXT_ROWS; ++y)
        for (int x = 0; x < TEXT_COLS; ++x) v.text[y][x] = ' ';
    v.games_to_win = 4;
    v.players = 1;
    v.scene_city = 0xFF;
    v.demo_city = 2;
    v.seed = 0xA22A1987u;
    az_music_init(&v.music);
    v.last_ms = prg32_ticks_ms();
    v.last_input = prg32_input_read();
    title_screen();
}

void azzurra_update(void) {
    uint32_t buttons = prg32_input_read();
    uint32_t buttons2 = prg32_input_read_player(1);
    /* A press waits for the next tick: a frame shorter than a tick runs none. */
    v.pending_pressed |= buttons & ~v.last_input;
    v.pending_pressed2 |= buttons2 & ~v.last_input2;
    v.last_input = buttons;
    v.last_input2 = buttons2;
    uint32_t now = prg32_ticks_ms();
    v.tick_accum += now - v.last_ms;
    v.last_ms = now;
    if (v.tick_accum > AZ_TICK_MS * MAX_CATCH_UP) v.tick_accum = AZ_TICK_MS * MAX_CATCH_UP;
    while (v.tick_accum >= AZ_TICK_MS) {
        v.tick_accum -= AZ_TICK_MS;
        uint32_t pressed = v.pending_pressed, pressed2 = v.pending_pressed2;
        v.pending_pressed = v.pending_pressed2 = 0;
        update_step(buttons, pressed, buttons2, pressed2);
    }
}

void azzurra_draw(void) {
    v.count = 0;
    switch (v.app) {
    case APP_TITLE:
        add_static();
        for (int i = 0; i < 4; ++i) add_player(i);
        sprite_add_1x(SPR_LOGO, (W - spr_w[SPR_LOGO]) / 2, 14, 32000);
        break;
    case APP_CHAMPION: {
        add_static();
        for (int i = 0; i < 4; ++i) add_player(i);
        sprite_add_1x(SPR_TROPHY, (W - spr_w[SPR_TROPHY]) / 2, 92, 30000);
        for (int i = 0; i < 24; ++i) sprite_add_1x(SPR_CONF0 + v.conf_k[i], 35 + v.conf_x[i], v.conf_y[i], 31000 + i);
        break;
    }
    default:
        add_match();
        break;
    }
    render();
}
